precision highp float;
varying vec2 v_uv0;
uniform sampler2D cc_spriteTexture;
uniform vec4 shineColor;
 uniform float shinePosition;
 uniform float slope;
 uniform float shineWidth;
vec4 frag() {
  vec4 baseColor = texture2D(cc_spriteTexture, v_uv0);
  if (baseColor.a > 0.1 && v_uv0.y > 0.0 && v_uv0.y < 1.0) {
    float distanceFromCenter = abs(v_uv0.x + slope * v_uv0.y - shinePosition);
    float shineEffect = 1.0 - smoothstep(0.0, shineWidth, distanceFromCenter);
    vec4 reducedShineColor = shineColor * 0.6;
    vec4 finalColor = baseColor + reducedShineColor * shineEffect;
    return finalColor;
  } else {
    return baseColor;
  }
}
void main() { gl_FragColor = frag(); }
